// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(address caller) internal {
        caller = msg.sender;
        vm.assume((caller != address(0) && (caller == c.DEPOSITOR_ACCOUNT() || caller != c.DEPOSITOR_ACCOUNT())));
        bool reverted;
        try c.setL1BlockValues(1,1,1,bytes32(0),1,bytes32(0),1,1) { reverted = false; } catch { reverted = true; }
        assertTrue((caller == c.DEPOSITOR_ACCOUNT() && reverted == false) || (caller != c.DEPOSITOR_ACCOUNT() && reverted == true));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
